import json
import re
import sys

def strict_object(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise ValueError('Duplicate JSON key: ' + key)
        result[key] = value
    return result
organization = sys.argv[6]
definitionName = sys.argv[7]
try:
    definitionVersion = int(sys.argv[3])
except Exception:
    definitionVersion = 0
strategyProvided = bool(sys.argv[8])
confirmationAccepted = sys.argv[10] == 'true'
strategy = None
errors = []
errors.extend(json.loads(sys.argv[11]))
errors.extend(json.loads(sys.argv[12]))
if definitionVersion < 1:
    errors.append('Workload Definition Version must be at least 1.')
if strategyProvided:
    try:
        strategy = json.loads(sys.argv[4], object_pairs_hook=strict_object)
    except Exception as exc:
        errors.append('Preferred Version Rollout Strategy is invalid JSON: ' + str(exc))
    if isinstance(strategy, dict):
        kind = strategy.get('ObjectType') or strategy.get('ClassId')
        allowed = {'ClassId', 'ObjectType'} if kind == 'workload.BatchDeployment' else {'ClassId', 'ObjectType', 'RolloutPercentages'}
        if kind not in ('workload.BatchDeployment', 'workload.CanaryDeployment'):
            errors.append('Rollout strategy type must be BatchDeployment or CanaryDeployment.')
        elif set(strategy) - allowed or strategy.get('ClassId', kind) != kind or strategy.get('ObjectType', kind) != kind:
            errors.append('Rollout strategy contains mismatched, read-only, or unsupported fields.')
        elif kind == 'workload.CanaryDeployment' and (not isinstance(strategy.get('RolloutPercentages', []), list) or any((not isinstance(v, int) or isinstance(v, bool) or v < 1 or (v > 100) for v in strategy.get('RolloutPercentages', [])))):
            errors.append('Canary RolloutPercentages must be integer percentages from 1 through 100.')
        strategy = {'ClassId': kind, 'ObjectType': kind, **({'RolloutPercentages': strategy.get('RolloutPercentages', [])} if kind == 'workload.CanaryDeployment' else {})}
    elif strategy is not None:
        errors.append('Preferred Version Rollout Strategy must be an object.')
status, statusCode = ('invalid', 400) if errors else ('ok', 200)
message = ' '.join(errors) if errors else 'Preferred-version request is valid.'
resultJson = json.dumps({'error': message}, separators=(',', ':')) if errors else '{}'
ready = True
organizationUrl = "/api/v1/organization/Organizations?$filter=Name eq '%s'&$select=Moid,Name" % sys.argv[9]
rolloutJson = json.dumps(strategy, separators=(',', ':')) if strategy is not None else ''

import json
import re
import sys
statusCode, lookupStatus, message = 502, "invalid-response", "Organization response is invalid"
organizationMoid, organizationJson = "", "{}"
inspectionComplete = False
try:
    payload = json.loads(sys.argv[1])
    if not isinstance(payload, dict): raise ValueError("Organization response must be an object")
    count, rows = payload.get("Count"), payload.get("Results")
    if isinstance(count, bool) or not isinstance(count, int) or count < 0: raise ValueError("Count must be a nonnegative integer")
    if not isinstance(rows, list): raise ValueError("Results must be an array")
    if count != len(rows): raise ValueError("Count and Results length differ; the bounded page is incomplete")
    if count > 2: raise ValueError("Count exceeds the two-row lookup bound")
    if count == 0: statusCode, lookupStatus, message = 404, "not-found", "No organization matched the exact requested name"
    elif count != 1: statusCode, lookupStatus, message = 409, "ambiguous", "More than one organization matched the exact requested name"
    else:
        item = rows[0]
        if not isinstance(item, dict) or item.get("Name") != sys.argv[2]: raise ValueError("Organization Name does not match exactly")
        if item.get("ObjectType") != "organization.Organization" or item.get("ClassId") != "organization.Organization": raise ValueError("Organization discriminators do not match")
        moid = item.get("Moid")
        pattern = r"[0-9a-fA-F]{24}" if sys.argv[3] == "Hex24" else r"[A-Za-z0-9][A-Za-z0-9._~-]{0,127}"
        if not isinstance(moid, str) or re.fullmatch(pattern, moid) is None: raise ValueError("Organization Moid is missing or malformed")
        organizationMoid = moid
        projected = {key:item[key] for key in ("Moid", "Name", "ObjectType", "ClassId")}
        organizationJson = json.dumps(projected, separators=(",", ":"))
        resultJson = json.dumps({"Count":1,"Results":[projected]}, separators=(",", ":"))
        statusCode, lookupStatus, message = 200, "exact", "Organization resolved exactly"
    inspectionComplete = True
except Exception as exc:
    statusCode, lookupStatus, message, inspectionComplete = 502, "invalid-response", str(exc), True
errorMessage = "" if statusCode == 200 else message
if statusCode != 200: resultJson = json.dumps({"status":lookupStatus,"error":message}, separators=(",", ":"))

