import json
import sys
status, statusCode, message, resultJson, ready = ('ok', 200, 'Preferred-version impact summarized', '{}', False)
impactResultJson = '{}'
targetAlreadyPreferred = sys.argv[10] == 'true'
try:
    target = json.loads(sys.argv[1])
    deploymentsBody = json.loads(sys.argv[2])
    family = json.loads(sys.argv[3])
    name = sys.argv[4]
    organizationMoid = sys.argv[5]
    confirmed = sys.argv[11] == 'true'
    org = target.get('Organization') if isinstance(target, dict) else None
    validation = target.get('ValidationInformation') if isinstance(target, dict) else None
    if not isinstance(target, dict) or target.get('Moid') != sys.argv[8] or target.get('Name') != name or (int(target.get('Version', 0)) != int(sys.argv[9])) or (not isinstance(org, dict)) or (org.get('Moid') != organizationMoid):
        status, statusCode, message = ('identity-mismatch', 409, 'Target item identity changed.')
    elif not isinstance(validation, dict) or validation.get('EngineState') != 'Updated' or validation.get('State') != 'Valid':
        status, statusCode, message = ('invalid', 422, 'Target definition must be Updated and Valid.')
    else:
        rows = deploymentsBody.get('Results') if isinstance(deploymentsBody, dict) else None
        count = deploymentsBody.get('Count') if isinstance(deploymentsBody, dict) else None
        if not isinstance(rows, list) or isinstance(count, bool) or (not isinstance(count, int)) or (count < 0):
            raise ValueError('Deployment impact response must contain a non-negative integer Count and Results array.')
        if count > 1000:
            status, statusCode, message = ('paging-required', 422, 'More than 1000 organization deployments require internal paging; this export fails closed before mutation.')
        elif count != len(rows):
            status, statusCode, message = ('incomplete-page', 422, 'Deployment impact Results are incomplete relative to Count; this export fails closed before mutation.')
        elif any((not isinstance(row, dict) or not isinstance(row.get('Organization'), dict) or row['Organization'].get('Moid') != organizationMoid for row in rows)):
            status, statusCode, message = ('identity-mismatch', 409, 'Deployment impact response contains an identity outside the requested organization.')
        else:
            affected = []
            for row in rows:
                mapper = row.get('WorkloadDefinitionReference') if isinstance(row, dict) else None
                if isinstance(mapper, dict) and mapper.get('DefinitionName') == name and (mapper.get('UsePreferredVersion') is True):
                    affected.append(row)
            byStatus = {}
            for row in affected:
                byStatus[row.get('Status', 'Unknown')] = byStatus.get(row.get('Status', 'Unknown'), 0) + 1
            active = sum((value for key, value in byStatus.items() if key != 'Draft'))
            if active and (not confirmed):
                status, statusCode, message = ('confirmation-required', 400, 'Confirm Active Deployment Rollout must be true because %d non-Draft deployments follow the preferred version.' % active)
            preferred = [row for row in family if row.get('PreferredVersion') is True]
            impactResultJson = json.dumps({'target': target, 'impact': {'followingPreferredCount': len(affected), 'activeFollowingPreferredCount': active, 'byStatus': byStatus}, 'currentPreferred': {'Moid': preferred[0].get('Moid'), 'Version': preferred[0].get('Version')} if preferred else None}, separators=(',', ':'), ensure_ascii=False)
            resultJson = impactResultJson
    if status != 'ok':
        resultJson = json.dumps({'error': message, 'mutationSubmitted': False}, separators=(',', ':'))
    ready = True
except Exception as exc:
    status, statusCode, message, resultJson, ready = ('malformed', 502, str(exc), json.dumps({'error': str(exc)}, separators=(',', ':')), True)
